const body = $input.item.json.body || $input.item.json;
const company_id = Number(body.company_id);
const modo = (body.modo === 'outreach') ? 'outreach' : 'blog';
if (!company_id) {
  return [{ json: { error: true, motivo: 'Falta company_id en el body del webhook.' } }];
}
// Tope por corrida (28-oct): 10 por defecto, de 1 a 20 — cuida la reputación del correo de la empresa
// y entra en un solo pedido a la IA.
const limite = Math.min(20, Math.max(1, parseInt(body.limite, 10) || 10));
// dry_run: arma los correos y los devuelve, sin crear borradores ni tocar el CRM.
const dry_run = body.dry_run === true;
// contexto (24-nov): dato de campaña opcional que manda quien corre el flujo (un evento, una temporada); la IA
// lo usa solo con los negocios a los que les aplica.
const contexto = typeof body.contexto === 'string' ? body.contexto.trim().slice(0, 300) : '';
return [{ json: { company_id, modo, limite, dry_run, contexto, error: false } }];

const __httpConTope = (o) => this.helpers.httpRequest(Object.assign({ timeout: 120000 }, o)); // 17-nov: tope por defecto de 2 min si la llamada no trae uno
const params = $('🔧 Extraer Parámetros').first().json;
// Quién recibe correo lo decide 🔍 Seleccionar Contactos (28-oct); acá solo se arman.
const sel = $('🔍 Seleccionar Contactos').first().json;
if (sel.sinLeads) return [{ json: { sinLeads: true, motivo: sel.motivo } }];
const modo = params.modo;
const G54_BASE_URL = 'https://apigrowth.mdarthurdigital.com';
const G54_AGENT_TOKEN = 'REDACTED_G54_AGENT_TOKEN';

let empresa = {};
try { empresa = $('📊 Obtener Empresa').first().json.data || {}; } catch (e) {}
const empresaNombre = empresa.name || 'Nuestra empresa';
const empresaWeb = empresa.website || '';
const empresaProp = (empresa.value_proposition || '').trim().replace(/\.+$/, '');
const empresaServicios = (empresa.products_services || '').split(',').map(s => s.trim()).filter(Boolean);
const empresaCobertura = (empresa.coverage || empresa.geography || '').trim().replace(/\.+$/, '');

// Blog: post más reciente (solo si modo === 'blog')
let post = null;
if (modo === 'blog') {
  try {
    const cms = $('🔗 Obtener CMS WordPress').first().json.data;
    if (!cms || !cms.is_active) {
      return [{ json: { sinLeads: true, motivo: 'La empresa no tiene WordPress conectado (Ajustes → CMS Integrations) — no hay ningún blog real que compartir.' } }];
    }
    const first = $('📰 WP: Obtener Posts').first().json;
    if (!first) {
      return [{ json: { sinLeads: true, motivo: 'El blog de la empresa no tiene ningún post publicado todavía.' } }];
    }
    const media = first._embedded && first._embedded['wp:featuredmedia'] && first._embedded['wp:featuredmedia'][0];
    post = {
      id: first.id,
      titulo: (first.title && first.title.rendered) || '',
      extracto: ((first.excerpt && first.excerpt.rendered) || '').replace(/<[^>]+>/g, '').trim(),
      url: first.link,
      imagen: media ? ((media.media_details && media.media_details.sizes && media.media_details.sizes.large && media.media_details.sizes.large.source_url) || media.source_url) : '',
    };
  } catch (e) {
    return [{ json: { sinLeads: true, motivo: 'No se pudo leer el blog real de la empresa (' + (e.message || e) + ').' } }];
  }
}

// Desde el 23-nov el correo lo arma G54 con su diseño único (aprobado por Don Marc): sin imagen de RRSS.

const candidatos = sel.candidatos || [];

// Correos en frío redactados por la IA con el perfil de la empresa (28-oct)
const redactados = {};
// Horario del pie en inglés para los correos en inglés (29-oct); si la IA no lo trae, queda el del perfil.
let horarioEn = '';
if (modo === 'outreach') {
  try {
    const j = JSON.parse($input.first().json.choices[0].message.content);
    horarioEn = String(j.horario_en || '').replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim().slice(0, 150);
    for (const x of (j.correos || [])) if (x && x.deal_id != null) redactados[String(x.deal_id)] = x;
  } catch (e) {}
}
const limpio = (t) => String(t || '').replace(/<[^>]*>/g, '').replace(/https?:\/\/\S+/g, '').replace(/\s+/g, ' ').trim();
const validar = (x) => {
  if (!x) return null;
  const idioma = x.idioma === 'en' ? 'en' : 'es';
  const asunto = limpio(x.asunto), titulo = limpio(x.titulo), boton = limpio(x.boton);
  // 24-nov: la IA a veces promete aunque la regla lo prohíbe; sin garantías que el perfil no dice
  const sinPromesas = (t) => t
    .replace(/guaranteeing/gi, 'helping ensure').replace(/guarantees/gi, 'helps ensure').replace(/guaranteed/gi, 'reliable').replace(/guarantee/gi, 'help ensure')
    .replace(/garantizando/gi, 'ayudando a asegurar').replace(/garantizamos/gi, 'buscamos asegurar').replace(/garantiza/gi, 'ayuda a asegurar').replace(/garantizad[oa]s?/gi, 'confiable');
  const parrafos = (Array.isArray(x.parrafos) ? x.parrafos : []).map(limpio).map(sinPromesas).filter(Boolean);
  const servicios = (Array.isArray(x.servicios) ? x.servicios : []).map(limpio).filter(s => s && s.length <= 60).slice(0, 4);
  const palabras = parrafos.join(' ').split(' ').length;
  if (asunto.length < 5 || asunto.length > 90 || !titulo || titulo.length > 60 || parrafos.length < 2 || parrafos.length > 4 || palabras < 30 || palabras > 180) return null;
  const may = (t) => t.charAt(0).toUpperCase() + t.slice(1); // por si la IA escribe todo en minúscula
  return { idioma, asunto: may(asunto), titulo: may(titulo), parrafos: parrafos.map(may), servicios: servicios.map(may), boton: boton && boton.length <= 40 ? may(boton) : '' };
};
// Idioma de respaldo, si la IA no respondió: por el teléfono o el lugar del prospecto
const idiomaDe = (f) => {
  const tel = String((f && f.telefono) || '').replace(/[^+\d]/g, '');
  const lugar = String((f && f.lugar) || '');
  if (/puerto rico|quebec|qu\u00e9bec/i.test(lugar) || /^\+1(787|939)/.test(tel)) return 'es';
  if (/^\+1\d{10}$/.test(tel) || /\b(USA|United States|EE\.? ?UU\.?|[A-Z]{2}\s*\d{5}|, (FL|NY|TX|CA|GA|NJ|IL|ON|BC|AB))\b/.test(lugar)) return 'en';
  return 'es';
};

// Las notas del CRM admiten 1000 caracteres: si se pasan, se acorta el texto descriptivo,
// nunca las marcas (no_contactar_email, outreach_borrador, blog:N), que son las que evitan repetir.
const notasCon = (notasViejas, marca) => {
  const t = (notasViejas ? notasViejas + ' | ' : '') + marca;
  if (t.length <= 1000) return t;
  const re = /(no_contactar_email[^|]*|outreach_borrador \S+|blog:\d+)/g;
  const marcas = Array.from(new Set((notasViejas.match(re) || []).map(s => s.trim())));
  const resto = notasViejas.replace(/(no_contactar_email[^|]*|outreach_borrador \S+|blog:\d+[^|]*)/g, '').replace(/(\s*\|\s*)+/g, ' | ').replace(/^\s*\|\s*|\s*\|\s*$/g, '').trim();
  const fijo = [...marcas, marca].join(' | ');
  const lugar = Math.max(0, 1000 - fijo.length - 3);
  return ((resto.slice(0, lugar) + ' | ') + fijo).slice(-1000);
};

// --- Diseño de G54 (23-nov) ---
// Camila ya no arma HTML: manda las partes (título, párrafos, lista, botón, idioma) y G54 arma el
// correo con su diseño único y el pie de la empresa (logo, dirección, contacto, horario y baja).
const esc = (t) => String(t || '');
const aLista = (v) => (Array.isArray(v) ? v : String(v || '').split(/[\n,;]+/)).map(x => String(x).trim()).filter(Boolean);
const empTel = aLista(empresa.phones)[0] || '';
const empMail = aLista(empresa.emails)[0] || '';
const empDir = String(empresa.address || '').trim();
const empHorario = String(empresa.business_hours || '').trim();
// Textos de WordPress: G54 escapa todo, así que las entidades (&#8217;, &amp;) se pasan a caracteres.
const sinEntidades = (t) => String(t || '').replace(/<[^>]*>/g, '').replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n)).replace(/&#x([0-9a-f]+);/gi, (m, n) => String.fromCharCode(parseInt(n, 16)))
  .replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&hellip;/g, '…').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
// HMAC-SHA256 en JavaScript puro (n8n no permite require('crypto')). Entradas en ASCII.
const sha256 = (bytes) => {
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const m = bytes.slice(); const l = m.length * 8; m.push(0x80); while (m.length % 64 !== 56) m.push(0);
  for (let i = 7; i >= 0; i--) m.push(i > 3 ? 0 : (l >>> (i * 8)) & 255);
  const r = (x, n) => (x >>> n) | (x << (32 - n)); const w = new Array(64);
  for (let o = 0; o < m.length; o += 64) {
    for (let i = 0; i < 16; i++) w[i] = (m[o + 4 * i] << 24) | (m[o + 4 * i + 1] << 16) | (m[o + 4 * i + 2] << 8) | m[o + 4 * i + 3];
    for (let i = 16; i < 64; i++) { const s0 = r(w[i - 15], 7) ^ r(w[i - 15], 18) ^ (w[i - 15] >>> 3), s1 = r(w[i - 2], 17) ^ r(w[i - 2], 19) ^ (w[i - 2] >>> 10); w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0; }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) { const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0, t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0; h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0; }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0; H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  const out = []; for (const x of H) out.push((x >>> 24) & 255, (x >>> 16) & 255, (x >>> 8) & 255, x & 255); return out;
};
const firmaBaja = (secreto, texto) => {
  const bytes = (s) => Array.from(String(s), ch => ch.charCodeAt(0) & 255);
  let k = bytes(secreto); if (k.length > 64) k = sha256(k); while (k.length < 64) k.push(0);
  const interno = sha256(k.map(x => x ^ 0x36).concat(bytes(texto)));
  return sha256(k.map(x => x ^ 0x5c).concat(interno)).map(x => x.toString(16).padStart(2, '0')).join('').slice(0, 20);
};
// Enlace de baja firmado (26-oct): lo atiende el flujo ✉️ Camila — Baja de correos, que marca el trato con
// no_contactar_email; los tratos marcados se saltean arriba. La firma impide dar de baja a otro cambiando el número.
const SECRETO_BAJA = 'REDACTED_CAMILA_BAJA_SECRET';
// La firma cubre solo empresa:trato; l=en solo cambia el idioma de la página de baja.
const urlBaja = (dealId, idioma) => 'https://n8n.mdarthurdigital.com/webhook/baja-correo-g54?c=' + params.company_id + '&d=' + dealId + '&t=' + firmaBaja(SECRETO_BAJA, params.company_id + ':' + dealId) + (idioma === 'en' ? '&l=en' : '');
const PIE = {
  es: { baja: 'Si no quieres recibir más correos de ' + empresaNombre + ', puedes darte de baja', aqui: 'aquí', horario: 'Horario' },
  en: { baja: 'If you would rather not receive more emails from ' + empresaNombre + ', you can unsubscribe', aqui: 'here', horario: 'Hours' },
};
const horarioDe = (idioma) => (idioma === 'en' && horarioEn) ? horarioEn : empHorario;
const footerTexto = (dealId, idioma = 'es') => { const P = PIE[idioma] || PIE.es; const empHorario = horarioDe(idioma); return ['--', empresaNombre, empDir, [empTel, empMail, empresaWeb].filter(Boolean).join(' · '),
  empHorario ? P.horario + ': ' + empHorario : ''].filter(Boolean).join('\n') + '\n\n' + P.baja + ': ' + urlBaja(dealId, idioma); };

// Motivo y origen de cada borrador (5-nov): G54 los muestra a quien aprueba, para que sepa
// a quién se le escribe y por qué. Salen solo de datos reales del trato, nunca inventados.
const ETAPAS = { new: 'nuevo', contacted: 'contactado', qualified: 'calificado', proposal: 'propuesta', negotiation: 'negociación' };
const ORIGENES = { whatsapp: 'WhatsApp', web: 'formulario web', manual: 'cargado a mano', agente: 'un agente de G54', importacion: 'importación', facebook: 'Facebook', instagram: 'Instagram' };
const correoVia = (n) => { const m = String(n || '').match(/Email encontrado vía ([^:]+):/); return m ? m[1].trim() : ''; };
const motivoDe = (d) => {
  const f = d.ficha || {};
  let m;
  if (modo === 'outreach') {
    m = 'Primer contacto: lo encontró Prospección' + (f.buscado_como ? ' buscando "' + f.buscado_como + '"' : '') +
      (f.lugar ? ' en ' + f.lugar : '') + (f.categoria ? ' (categoría: ' + f.categoria + ')' : '') + '.' +
      (correoVia(d.notas) ? ' Correo sacado de ' + correoVia(d.notas) + '.' : '') +
      ' Está en la etapa "nuevo" del CRM y todavía no recibió ningún correo.';
  } else {
    m = 'Nutrir: se le comparte el artículo nuevo del blog "' + ((post && post.titulo) || '').replace(/<[^>]*>/g, '') + '".' +
      ' Es un contacto del CRM' + (d.etapa ? ' en la etapa "' + (ETAPAS[d.etapa] || d.etapa) + '"' : '') +
      (ORIGENES[d.origen] ? ', llegó por ' + ORIGENES[d.origen] : '') + ', y no recibió este artículo.';
  }
  if (d.reintento) m += ' Se vuelve a armar porque el borrador anterior falló al enviarse.';
  return m.slice(0, 500);
};
const origenDe = (d) => {
  if (modo === 'outreach') return ('Prospección' + (correoVia(d.notas) ? ' · correo de ' + correoVia(d.notas) : '')).slice(0, 120);
  return ('CRM · ' + (ORIGENES[d.origen] || d.origen || 'sin origen')).slice(0, 120);
};

// Armar el email por cada lead (personalizado)
const salida = candidatos.map(d => {
  let asunto, partes, texto, notaNueva, conIa = false, idiomaCorreo = 'es';

  if (modo === 'outreach') {
    const negocio = d.nombre || '';
    const f = d.ficha || {};
    const ia = validar(redactados[String(d.id)]);
    let idioma, titulo, parrafos, servicios, textoBoton;
    if (ia) {
      ({ idioma, asunto, titulo, parrafos, servicios } = ia);
      textoBoton = ia.boton || (idioma === 'en' ? 'Visit ' + empresaNombre : 'Conocer ' + empresaNombre);
    } else {
      idioma = idiomaDe(f);
      const rubro = f.categoria || f.buscado_como;
      if (idioma === 'en') {
        asunto = (empresaNombre + ' for ' + (negocio || 'your business')).slice(0, 60);
        titulo = 'Hello' + (negocio ? ', ' + negocio : '');
        parrafos = [
          'We came across ' + (negocio || 'your business') + (f.lugar ? ' in ' + f.lugar : '') + ' and think what we do at ' + empresaNombre + ' could be useful to you.',
          'If it sounds interesting, just reply to this email and we will tell you more.',
        ];
        servicios = []; // los nombres del perfil pueden estar en otro idioma
        textoBoton = 'Visit ' + empresaNombre;
      } else {
        asunto = (empresaNombre + ' para ' + (negocio || 'tu negocio')).slice(0, 60);
        titulo = 'Hola' + (negocio ? ', ' + negocio : '');
        parrafos = [
          'Encontramos ' + (negocio || 'su negocio') + (rubro ? ' (' + rubro + ')' : '') + (f.lugar ? ' en ' + f.lugar : '') + ' y creemos que lo que hacemos en ' + empresaNombre + ' puede serles útil.',
          'Somos ' + empresaNombre + (empresaProp ? ': ' + empresaProp : '') + '.' + (empresaCobertura ? ' Trabajamos en ' + empresaCobertura + '.' : ''),
          'Si les interesa, respondan este correo y les contamos más.',
        ];
        servicios = empresaServicios.slice(0, 4);
        textoBoton = 'Conocer ' + empresaNombre;
      }
    }
    conIa = !!ia;
    idiomaCorreo = idioma;
    partes = {
      titulo, parrafos, idioma,
      ...(servicios.length ? { lista: servicios } : {}),
      ...(/^https?:\/\//.test(empresaWeb) ? { boton: { texto: textoBoton, url: empresaWeb } } : {}),
    };
    texto = parrafos.join('\n\n') + (servicios.length ? '\n\n' + servicios.map(s => '- ' + s).join('\n') : '') + (empresaWeb ? '\n\n' + empresaWeb : '') + '\n\n' + footerTexto(d.id, idioma);
    notaNueva = notasCon(d.notas || '', 'outreach_borrador ' + new Date().toISOString().slice(0,10));
  } else {
    const nombre = (d.nombre || '').split(' ')[0] || 'hola';
    asunto = post.titulo ? `${empresaNombre} — ${sinEntidades(post.titulo)}` : `Novedades de ${empresaNombre}`;
    const tituloPost = sinEntidades(post.titulo) || 'Nueva publicación';
    partes = {
      titulo: tituloPost,
      parrafos: ['Hola ' + nombre + ',', sinEntidades(post.extracto) || 'Publicamos una nota nueva en nuestro blog.'].filter(Boolean),
      boton: { texto: 'Leer la nota completa', url: post.url },
      idioma: 'es',
    };
    texto = `${sinEntidades(post.titulo)}\n\n${sinEntidades(post.extracto)}\n\nLeer más: ${post.url}\n\n${footerTexto(d.id)}`;
    notaNueva = notasCon(d.notas || '', 'blog:' + post.id + ' en revisión ' + new Date().toISOString().slice(0,10));
  }

  return {
    json: {
      deal_id: d.id,
      email: d.email,
      nombre: d.nombre || null,
      articulo_id: null, // G54 rechaza el WP post id real con 422 'articulo id invalido' -- articulo_id referencia una tabla propia distinta de G54, no el post_id de WordPress (confirmado en vivo 22-sep). El dedupe real de 'ya se le mando este post' sigue viviendo en el marker de texto en notas, mas abajo -- no depende de este campo.
      asunto,
      partes,
      enlace_baja: urlBaja(d.id, idiomaCorreo),
      texto,
      notas_nueva: notaNueva,
      con_ia: conIa,
      idioma: idiomaCorreo,
      reintento: !!d.reintento,
      motivo: motivoDe(d),
      origen: origenDe(d),
    }
  };
});

return salida;

const items = $input.all();
let quedan = 0; try { quedan = $('🔍 Seleccionar Contactos').first().json.quedan || 0; } catch (e) {}
let armados = []; try { armados = $('🔍 Filtrar y Armar Emails').all().map(i => i.json).filter(j => !j.sinLeads); } catch (e) {}
const extra = { quedan_para_la_proxima: quedan, redactados_con_ia: armados.filter(j => j.con_ia).length, reintentos: armados.filter(j => j.reintento).length };
if ($('🔧 Extraer Parámetros').first().json.dry_run && !(items.length === 1 && items[0].json.sinLeads)) {
  return [{ json: { ok: true, prueba: true, se_crearian: armados.length, ...extra, detalle: armados.map(j => ({ deal_id: j.deal_id, email: j.email, idioma: j.idioma, con_ia: j.con_ia, reintento: j.reintento, motivo: j.motivo, origen: j.origen, asunto: j.asunto, texto: j.texto })) } }];
}
if (items.length === 1 && items[0].json.sinLeads) {
  return [{ json: { ok: true, borradores_creados: 0, fallidos: 0, motivo: items[0].json.motivo, ...extra } }];
}
const fallidos = items.filter(i => i.json.error).length;
const exitosos = items.length - fallidos;
const errores = items.filter(i => i.json.error).map(i => (i.json.error.message || '').slice(0,200));
return [{ json: { ok: true, borradores_creados: exitosos, fallidos, errores: fallidos ? errores : undefined, ...extra } }];

const __httpConTope = (o) => this.helpers.httpRequest(Object.assign({ timeout: 120000 }, o)); // 17-nov: tope por defecto de 2 min si la llamada no trae uno
// Elige a quién escribirle en esta corrida (28-oct): filtra el tablero, respeta el tope por corrida y,
// en modo outreach, arma el pedido a la IA para redactar cada correo con el perfil de la empresa.
const params = $('🔧 Extraer Parámetros').first().json;
const modo = params.modo;
const limite = params.limite;
const G54_BASE_URL = 'https://apigrowth.mdarthurdigital.com';
const MODELO_TRIVIAL = { model: 'openai/gpt-oss-120b', max_tokens: 16, reasoning_effort: 'low', messages: [{ role: 'user', content: 'ok' }] };
const sinLeads = (motivo) => [{ json: { sinLeads: true, motivo, candidatos: [], quedan: 0, groq_body: MODELO_TRIVIAL } }];

let empresa = {};
try { empresa = $('📊 Obtener Empresa').first().json.data || {}; } catch (e) {}

// Blog: hace falta un post real para saber qué marca buscar en las notas
let postId = '';
if (modo === 'blog') {
  try {
    const cms = $('🔗 Obtener CMS WordPress').first().json.data;
    if (!cms || !cms.is_active) return sinLeads('La empresa no tiene WordPress conectado (Ajustes → CMS Integrations) — no hay ningún blog real que compartir.');
    const first = $('📰 WP: Obtener Posts').first().json;
    if (!first || !first.id) return sinLeads('El blog de la empresa no tiene ningún post publicado todavía.');
    postId = String(first.id);
  } catch (e) {
    return sinLeads('No se pudo leer el blog real de la empresa (' + (e.message || e) + ').');
  }
}

// Board CRM
let board = {};
try { board = $('📋 Obtener Board CRM').first().json || {}; } catch (e) {}
const excluidas = ['closed', 'lost'];
let deals = [];
for (const etapa of Object.keys(board)) {
  if (excluidas.includes(etapa)) continue;
  const arr = Array.isArray(board[etapa]) ? board[etapa] : [];
  for (const d of arr) if (d && d.id) deals.push({ ...d, _etapa: etapa });
}

// Borradores que ya armó Camila: si el último de un trato falló al enviarse, se puede volver a armar.
// Un borrador cancelado NO se reintenta: cancelar en el panel quiere decir "a este no".
const tipoModo = modo === 'outreach' ? 'nurture_frio' : 'nurture_calificado';
const ultimoPorTrato = {};
try {
  const tok = $('🔐 G54: Login Sesión').first().json.access_token;
  const get = (path) => __httpConTope({ method: 'GET', url: G54_BASE_URL + path, headers: { Authorization: 'Bearer ' + tok, Accept: 'application/json' }, json: true, timeout: 30000 });
  const lista = [];
  const pend = await get('/api/email-drafts');
  lista.push(...((pend && pend.data) || []));
  for (let page = 1; page <= 10; page++) {
    const h = await get('/api/email-drafts/historial?page=' + page);
    lista.push(...((h && h.data) || []));
    if (!h || !h.last_page || page >= h.last_page) break;
  }
  for (const b of lista) {
    if (!b.crm_deal_id || b.tipo !== tipoModo) continue;
    const prev = ultimoPorTrato[b.crm_deal_id];
    if (!prev || String(b.created_at) > String(prev.created_at)) ultimoPorTrato[b.crm_deal_id] = b;
  }
} catch (e) {
  // sin historial no se reintenta nada: es lo seguro
}
const fallo = (d) => (ultimoPorTrato[d.id] || {}).estado === 'fallido';

const notas = (d) => d.notas || '';
const esProspecto = (d) => notas(d).includes('Prospección AI');
// baja_at: campo propio de G54 desde el 4-nov; la marca en las notas sigue valiendo para las bajas de antes
const puedeEscribirse = (d) => d.email && !d.baja_at && !notas(d).includes('no_contactar_email');

let candidatos;
if (modo === 'outreach') {
  // Primer contacto en frío: solo prospectados que nadie movió todavía de "new"
  candidatos = deals.filter(d => puedeEscribirse(d) && esProspecto(d) && d._etapa === 'new' &&
    (!notas(d).includes('outreach_borrador') || fallo(d)));
} else {
  // Nutrir con el blog: contactos activos con correo, nunca un prospectado en frío que sigue en "new"
  // (no pidió nada todavía; para él está el primer contacto)
  const marker = 'blog:' + postId;
  candidatos = deals.filter(d => puedeEscribirse(d) && !(esProspecto(d) && d._etapa === 'new') &&
    (!notas(d).includes(marker) || fallo(d)));
}

if (candidatos.length === 0) {
  return sinLeads(modo === 'outreach'
    ? 'No hay leads nuevos de prospección con email pendientes de un primer contacto.'
    : 'No hay ningún lead con email pendiente de recibir este post — ya se les mandó, o no hay ningún lead con email guardado todavía.');
}

// Tope por corrida: los más viejos primero, el resto queda para la próxima
candidatos.sort((a, b) => Number(a.id) - Number(b.id));
const quedan = Math.max(0, candidatos.length - limite);
candidatos = candidatos.slice(0, limite);

// Datos del prospecto que dejó Prospección en las notas
const deNotas = (d, re) => { const m = notas(d).match(re); return m ? m[1].trim() : ''; };
const ficha = (d) => ({
  deal_id: d.id,
  nombre: d.nombre || '',
  categoria: deNotas(d, /Categoría:\s*([^.]+)\./),
  buscado_como: deNotas(d, /buscando "([^"]+)"/),
  lugar: deNotas(d, /\sen ([^,]+(?:,[^,]+)*?), con Foursquare/),
  web: deNotas(d, /Sitio:\s*(https?:\/\/\S+?)\.?(?:\s|$)/),
  telefono: d.telefono || '',
});
const slim = candidatos.map(d => ({ id: d.id, nombre: d.nombre || '', email: d.email, telefono: d.telefono || '', notas: notas(d), ficha: ficha(d), reintento: fallo(d), etapa: d._etapa || '', origen: d.origen || '' }));

if (modo !== 'outreach') {
  return [{ json: { sinLeads: false, candidatos: slim, quedan, groq_body: MODELO_TRIVIAL } }];
}

const perfil = {
  nombre: empresa.name || '',
  descripcion: empresa.description || '',
  propuesta_de_valor: empresa.value_proposition || '',
  rubro: empresa.industry || '',
  productos_y_servicios: empresa.products_services || '',
  cobertura: empresa.coverage || empresa.geography || empresa.base_city || '',
  cliente_ideal: empresa.target_market || '',
  web: empresa.website || '',
  direccion: empresa.address || '',
  horario: empresa.business_hours || '',
};
const sistema = [
  'Redactas correos cortos y honestos de primer contacto en nombre de una empresa (su perfil va en el mensaje), uno para cada negocio de la lista.',
  'Escribe como la empresa, en plural ("somos", "we"). No firmes con un nombre de persona ni te presentes como una persona.',
  'Reglas:',
  '1) Usa SOLO lo que dice el perfil de la empresa. No inventes precios, descuentos, plazos, clientes, cifras, premios ni garantías.',
  '2) El primer párrafo dice, de forma concreta, para qué le sirve la empresa a ESE tipo de negocio: piensa en su trabajo real según su categoría y cómo se lo buscó (qué mueve, qué le preocupa, cuándo lo necesita). Nada de frases que servirían para cualquier negocio. Si la relación no es clara, habla en general, sin inventar.',
  '2b) Usa una sola ventaja de la propuesta de valor, la que más le importe a ese tipo de negocio, y di por qué le sirve. No enumeres todo lo que hace la empresa.',
  '2c) Los párrafos NO nombran ningún servicio de la lista "servicios" (esa lista se muestra sola debajo del texto). Prohibido escribir "we offer/we provide/ofrecemos" seguido de la lista: el texto explica el porqué; la lista, el qué.',
  '2e) No afirmes nada sobre ese negocio en particular que no esté en su ficha (que participa en un evento, qué envía, cuántas obras mueve, cómo trabaja): habla del tipo de negocio en general ("galleries often…", "las galerías suelen…"). Su nombre puede ir en el asunto o en el saludo, no en afirmaciones.',
  '2d) No le digas al negocio lo que necesita ("X needs/requires", "ustedes necesitan"): describe lo que suele pasar en ese tipo de trabajo y ofrece ayuda. No uses "garantizamos/guarantee" ni promesas que el perfil no diga con esas palabras.',
  '3) No digas que visitaste el negocio ni que ya lo conocen. Puedes decir que encontraste el negocio en su ciudad.',
  '4) idioma: "en" si el negocio está en EE. UU. o Canadá (salvo Quebec y Puerto Rico) o su teléfono empieza con +1 y no hay otra señal; "es" en cualquier otro caso. Todo el correo va en ese idioma, también los servicios.',
  '5) Tono profesional y cercano. Ortografía normal: cada oración empieza con mayúscula. No escribas palabras enteras en mayúsculas, ni emojis, ni signos de exclamación.',
  '6) asunto: máximo 60 caracteres, sin palabras de spam (gratis, urgente, oferta, free, urgent), que nombre al negocio o a su rubro y diga algo útil para ellos; no uses el mismo molde "Negocio – servicio" en todos.',
  '7) parrafos: 2 o 3 párrafos de texto plano (sin HTML ni enlaces), entre 55 y 100 palabras en total. El último párrafo SIEMPRE termina con una pregunta concreta y fácil de contestar respondiendo este correo, ligada a su trabajo (por ejemplo, si tienen un envío próximo o qué necesitarían cotizar). Nada de "contact us to discuss" ni frases vacías.',
  '7b) Revisa la gramática antes de responder: concordancia de sujeto y verbo, artículos y tiempos, en inglés y en español. Cada correo debe sonar escrito por una persona del rubro, no por una plantilla; varía cómo empiezan los correos entre un negocio y otro.',
  '8) titulo: de 3 a 7 palabras, para la cabecera del correo.',
  '9) servicios: de 2 a 3 servicios del perfil que de verdad le sirvan a ese tipo de negocio, con nombres cortos traducidos por completo al idioma del correo (sin mezclar idiomas). Deja fuera los que no encajan con su categoría (por ejemplo, un servicio pensado para fábricas no va en el correo a una galería de arte).',
  '10) boton: de 2 a 4 palabras, lleva a la web de la empresa.',
  '11) Si dices dónde está la empresa, usa la ciudad de su dirección (direccion), no la de cobertura.',
  '12) horario_en: el horario del perfil traducido al inglés, con el mismo contenido; vacío si el perfil no tiene horario.',
  '13) contexto: si el mensaje trae "contexto" (un evento o una temporada), menciónalo en una frase solo en los correos de negocios a los que de verdad les aplica, con las palabras de ese contexto y sin agregar fechas ni datos que no estén ahí. Si no viene o no aplica, no inventes ningún evento.',
  'Devuelve solo JSON: {"horario_en":"","correos":[{"deal_id":0,"idioma":"es","asunto":"","titulo":"","parrafos":[""],"servicios":[""],"boton":""}]}, un elemento por negocio, con el mismo deal_id.',
].join('\n');
const groq_body = {
  model: 'openai/gpt-oss-120b',
  temperature: 0.5,
  reasoning_effort: 'medium',
  max_tokens: 14000,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: sistema },
    { role: 'user', content: JSON.stringify(Object.assign({ empresa: perfil, negocios: slim.map(s => s.ficha) }, params.contexto ? { contexto: params.contexto } : {})) },
  ],
};
return [{ json: { sinLeads: false, candidatos: slim, quedan, groq_body } }];

const __httpConTope = (o) => this.helpers.httpRequest(Object.assign({ timeout: 120000 }, o)); // 17-nov: tope por defecto de 2 min si la llamada no trae uno
// 🔓 Sesiones G54 (17-nov): cada login maestro crea un token que no vence y n8n guarda la salida de cada corrida.
// Este nodo deja pasar todo igual, anota el token nuevo y cierra los de corridas anteriores de este mismo login
// (más de 30 min: ninguna corrida dura tanto). En reposo queda como mucho una sesión abierta por login.
const BASE = (() => { try { return String("https://apigrowth.mdarthurdigital.com").replace(/\/+$/, ''); } catch (e) { return ''; } })();
const st = $getWorkflowStaticData('global');
const k = 'sesionesG54__' + "\ud83d\udd10 G54: Login Sesi\u00f3n";
const ahora = Date.now();
const quedan = [];
for (const s of (Array.isArray(st[k]) ? st[k] : [])) {
  if (ahora - s.t > 30 * 60e3) {
    try { await __httpConTope({ method: 'POST', url: s.b + '/api/auth/logout', headers: { Authorization: 'Bearer ' + s.tok, Accept: 'application/json' }, json: true, timeout: 5000 }); } catch (e) {}
  } else quedan.push(s);
}
const tok = $input.item.json && $input.item.json.access_token;
if (tok && BASE) quedan.push({ tok, b: BASE, t: ahora });
st[k] = quedan.slice(-50);
return $input.item;
